#!/bin/bash
# ============================================================================
# check-scope.sh — PreToolUse hook for Edit|Write
# ============================================================================
# Warns when Claude edits files outside expected directories.
# Does NOT block — provides context so Claude can self-correct.
#
# DO NOT EDIT THIS FILE TO CUSTOMIZE IT. bin/update.sh copies it over on every
# framework update, which would silently revert your changes. Set ALLOWED_DIRS
# and ALLOWED_FILES_EXTRA in .claude/project.conf instead — that file is never
# touched by the updater.
# ============================================================================

INPUT=$(cat)
FILE_PATH=$(echo "$INPUT" | jq -r '.tool_input.file_path // empty')

if [ -z "$FILE_PATH" ]; then
  exit 0
fi

# --- Project-local configuration --------------------------------------------
# Resolved relative to this script so it works regardless of the caller's
# working directory.
HOOK_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_CONF="$HOOK_DIR/../project.conf"
# shellcheck source=/dev/null
[ -f "$PROJECT_CONF" ] && . "$PROJECT_CONF"

# Framework defaults — applied only where project.conf left a value UNSET.
# Tested with +x rather than :- so that explicitly setting a variable to the
# empty string means "match nothing", instead of silently restoring the default.
if [ -z "${ALLOWED_DIRS+x}" ]; then
  ALLOWED_DIRS="src/ tests/ docs/ .claude/"
fi

# Common project-root files across Python/Node/Rust/Go/etc. so first-time
# edits don't trigger spurious scope warnings. Extend per project with
# ALLOWED_FILES_EXTRA rather than replacing this.
if [ -z "${ALLOWED_FILES+x}" ]; then
  ALLOWED_FILES="CLAUDE.md README.md docs/CURRENT_SPRINT.md docs/LINEAR_SNAPSHOT.md"
  ALLOWED_FILES="$ALLOWED_FILES pyproject.toml package.json package-lock.json"
  ALLOWED_FILES="$ALLOWED_FILES Cargo.toml Cargo.lock go.mod go.sum tsconfig.json"
  ALLOWED_FILES="$ALLOWED_FILES Makefile .gitignore .claudeignore .mcp.json .linear.toml"
fi
ALLOWED_FILES="$ALLOWED_FILES ${ALLOWED_FILES_EXTRA:-}"
# ----------------------------------------------------------------------------

# Normalize Windows backslashes so matching works for the absolute paths the
# Edit/Write tools report on Windows (C:\Users\...\tests\x.py).
# '\134' is the POSIX octal escape for a backslash. Written this way because
# tr '\\' '/' makes GNU tr warn "unescaped backslash at end of string is not
# portable" on stderr on every single edit, and trips shellcheck SC1003.
FILE_PATH_NORM=$(printf '%s' "$FILE_PATH" | tr '\134' '/')
BASE_NAME="${FILE_PATH_NORM##*/}"

IN_SCOPE=false

# Directory match — the directory must start the path or follow a slash, so
# "src/" does not match "vendor/notsrc/x.py".
for DIR in $ALLOWED_DIRS; do
  case "$FILE_PATH_NORM" in
    "$DIR"*|*/"$DIR"*) IN_SCOPE=true; break ;;
  esac
done

# File match — bare names match the basename, entries containing a slash match
# a path suffix. Both are exact rather than substring, so an entry like
# "Makefile" no longer lets "build/Makefile-gen/x.py" through.
if [ "$IN_SCOPE" = false ]; then
  for ALLOWED in $ALLOWED_FILES; do
    case "$ALLOWED" in
      */*)
        case "$FILE_PATH_NORM" in
          "$ALLOWED"|*/"$ALLOWED") IN_SCOPE=true; break ;;
        esac
        ;;
      *)
        if [ "$BASE_NAME" = "$ALLOWED" ]; then
          IN_SCOPE=true
          break
        fi
        ;;
    esac
  done
fi

if [ "$IN_SCOPE" = false ]; then
  # Built with jq so backslashes and quotes in the path are escaped correctly.
  # A raw heredoc emits invalid JSON for Windows paths.
  jq -n --arg ctx "SCOPE WARNING: You're editing '$FILE_PATH' which is outside the expected directories ($ALLOWED_DIRS). Verify this file is in scope for the current task." \
    '{hookSpecificOutput: {hookEventName: "PreToolUse", additionalContext: $ctx}}'
fi

# Always allow — this is advisory, not blocking
exit 0
